export const EXTERIOR_TUNING_LABELS={splitter:'FRONT LIP / SPLITTER',diffuser:'REAR DIFFUSER',fenders:'FENDERS',widebody:'BODY WIDTH',grille:'GRILLE',exhaustTips:'EXHAUST OUTLETS',lightDesign:'LIGHT DESIGN',paintFinish:'PAINT FINISH',livery:'BODY WRAP',decals:'DECALS',windowTint:'WINDOW TINT'};
