export const EXTERIOR_TUNING_PRICES={splitter:{stock:0,none:0,street:850,race:1600},diffuser:{stock:0,none:0,street:750,race:1450},fenders:{stock:0,vented:1800,carbon:3400},widebody:{stock:0,bolt:2800,gt:5200},grille:{stock:0,mesh:650,billet:900},exhaustTips:{stock:0,single:450,twin:900,quad:1300},lightDesign:{stock:0,projector:1600,yellow:950,led:2400},paintFinish:{stock:0,gloss:900,satin:1100,metallic:1700},livery:{stock:0,stripes:1200,sweep:1800,rally:2200},decals:{stock:0,none:0,club:450,works:700},windowTint:{stock:0,light:450,medium:650,dark:850}};
export function exteriorCompatibility(s,key,id){return key==='widebody'&&id==='gt'&&(!s.tyreWidth||s.tyreWidth==='stock')?'GT arches require WIDE or EXTRA-WIDE WHEELS.':'';}
export function sanitizeExteriorSelection(s){if(exteriorCompatibility(s,'widebody',s.widebody))s.widebody='stock';}
export const frontLip=s=>!s.splitter||s.splitter==='stock'?s.frontBumper||'stock':s.splitter;
export const rearDiffuser=s=>!s.diffuser||s.diffuser==='stock'?s.rearBumper||'stock':s.diffuser;
export const aeroPartMass=id=>({none:-3,stock:0,street:1,race:3}[id]??0);
export const tintTransmission=s=>({stock:.85,light:.70,medium:.50,dark:.35}[s.windowTint]??.85);
export function outletPositions(kind,s){return s.exhaustTips==='single'?[.62]:s.exhaustTips==='twin'?[.56,.76]:s.exhaustTips==='quad'?[-.54,-.38,.38,.54]:kind==='muscle'?[-.70,.70]:kind==='wedge'?[.60]:[.61,.77];}
export const outletHeight=s=>s.exhaustTips==='single'?.18:s.exhaustTips!=='stock'||s.rearBumper!=='stock'?.21:.32;
export function lampSpecification(s={}){return {stock:{color:0xd2eaff,power:1,range:90,angle:.30},projector:{color:0xe5edff,power:1.06,range:108,angle:.25},yellow:{color:0xffd36c,power:.95,range:76,angle:.35},led:{color:0xdaeeff,power:1.18,range:115,angle:.29}}[s.lightDesign]||{color:0xd2eaff,power:1,range:90,angle:.30};}
export function resolveExteriorTuning(s){
 const wide=s.widebody==='gt'?2:s.widebody==='bolt'?1:0,cornerMass=(s.fenders==='carbon'?-1:s.fenders==='vented'?.5:0)+[0,2,4][wide];
 const componentMass={hood:s.hood==='carbon'?-8:s.hood==='scoop'?2:s.hood==='vented'?.8:0,skirtLeft:s.sideSkirts==='street'?.5:s.sideSkirts==='race'?1:0,skirtRight:s.sideSkirts==='street'?.5:s.sideSkirts==='race'?1:0,fenderFL:cornerMass,fenderFR:cornerMass,fenderRL:cornerMass,fenderRR:cornerMass,grille:s.grille==='mesh'?-.4:s.grille==='billet'?.6:0,exhaustTip:s.exhaustTips==='single'?-1:s.exhaustTips==='quad'?2:0};
 return {trackExtra:[0,.03,.06][wide],dragExtra:[0,.012,.027][wide],componentMass,mass:Object.values(componentMass).reduce((a,b)=>a+b,0),transmission:tintTransmission(s)};
}
